    topic: 'symbols',
    q: { ko: '지금 부르는 애국가의 곡을 지은 사람은 누구입니까?', lo: 'ໃຜເປັນຜູ້ແຕ່ງທຳນອງເພງ 애국가 ທີ່ຮ້ອງກັນໃນປະຈຸບັນ?', th: 'ใครเป็นผู้ประพันธ์ทำนองเพลง 애국가 ที่ร้องกันในปัจจุบัน?', vi: 'Ai là người sáng tác nhạc cho bài 애국가 đang được hát hiện nay?' },
